groupby_with_catalog_display.code:
{{#catalogCollection "AllRetailProducts" as |items|}}
  {{#groupBy items field="category" as |groups|}}
    {{#each groups as |group|}}
      <h2>{{group.key.category}} ({{group.count}} items)</h2>
      {{#each group.items as |product|}}
        <div class="product-card">
          <img src="{{product.imageUrl}}" alt="{{product.name}}" width="200">
          <h3>{{product.name}}</h3>
          <p>{{product.description}}</p>
          {{#if product.onSale}}
            <s>${{numberFormat product.price "0.00"}}</s>
            <strong>${{numberFormat product.salePrice "0.00"}}</strong>
          {{else}}
            <p>${{numberFormat product.price "0.00"}}</p>
          {{/if}}
          <a href="{{product.url}}">Shop Now</a>
        </div>
      {{/each}}
    {{/each}}
  {{/groupBy}}
{{/catalogCollection}}

sortby_price_ascending.code:
{{#catalogCollection "AllRetailProducts" as |items|}}
  {{#sortBy items field="price" order="asc" as |sorted|}}
    {{#each sorted as |product|}}
      <div class="product-row">
        {{product.name}} — ${{numberFormat product.price "0.00"}}
      </div>
    {{/each}}
  {{/sortBy}}
{{/catalogCollection}}

sort_then_group.code:
{{#sortBy items field="estimatedDeliveryDate" order="asc" as |sorted|}}
  {{#groupBy sorted field="estimatedDeliveryDate" as |groups|}}
    {{#each groups as |group|}}
      <h3>Arriving {{group.key.estimatedDeliveryDate}} ({{group.count}} items)</h3>
      {{#each group.items as |item|}}
        <p>{{item.name}}</p>
      {{/each}}
    {{/each}}
  {{/groupBy}}
{{/sortBy}}

group_then_sort_within.code:
{{#catalogCollection "AllRetailProducts" as |items|}}
  {{#groupBy items field="shippingMethod" as |groups|}}
    {{#each groups as |group|}}
      <h3>{{group.key.shippingMethod}} ({{group.count}} items)</h3>
      {{#sortBy group.items field="price" order="asc" as |sorted|}}
        {{#each sorted as |product|}}
          {{product.name}} — ${{numberFormat product.price "0.00"}}
        {{/each}}
      {{/sortBy}}
    {{/each}}
  {{/groupBy}}
{{/catalogCollection}}

sort_group_sort_composition.code:
{{#sortBy items field="estimatedDeliveryDate" order="asc" as |sorted|}}
  {{#groupBy sorted field="shippingMethod,estimatedDeliveryDate" as |groups|}}
    {{#each groups as |group|}}
      <h3>{{group.key.shippingMethod}} — {{group.key.estimatedDeliveryDate}}</h3>
      {{#sortBy group.items field="price" order="desc" as |highToLow|}}
        {{#each highToLow as |item|}}
          {{item.name}} — ${{numberFormat item.price "0.00"}}
        {{/each}}
      {{/sortBy}}
    {{/each}}
  {{/groupBy}}
{{/sortBy}}

rei_order_confirmation.code:
{{#sortBy xmldata.ShipTos.ShipTo field="LineItems.ItemFirstPromisedDate" order="asc" as |sorted|}}
{{#groupBy sorted field="LineItems.ItemShippingMethod,LineItems.ItemFirstPromisedDate" as |groups|}}
{{#each groups as |group|}}
  <div class="shipment-group">
    <h3>
      {{group.key.LineItems.ItemShippingMethod}}
      — Arriving {{dateFormat group.key.LineItems.ItemFirstPromisedDate "MMM dd, yyyy"}}
      ({{group.count}} item{{#ifGt group.count 1}}s{{/ifGt}})
    </h3>
    {{#sortBy group.items field="LineItems.ItemPrice" order="desc" as |sortedItems|}}
    {{#each sortedItems as |item|}}
      <div class="line-item">
        <span>{{item.LineItems.ItemName}}</span>
        <span>Qty: {{item.LineItems.ItemQuantity}}</span>
        <span>${{numberFormat item.LineItems.ItemPrice "0.00"}}</span>
      </div>
    {{/each}}
    {{/sortBy}}
  </div>
{{/each}}
{{/groupBy}}
{{/sortBy}}

empty_state_handling.code:
{{#groupBy items field="category" as |groups|}}
  {{#if groups}}
    {{#each groups as |group|}}
      <h2>{{group.key.category}}</h2>
      {{#each group.items as |item|}}{{item.name}}{{/each}}
    {{/each}}
  {{else}}
    <p>No products available.</p>
  {{/if}}
{{/groupBy}}

multi_field_sort_tiebreaker.code:
{{#sortBy products field="priority,name" order="desc" as |sorted|}}
  {{#each sorted as |p|}}
    {{p.priority}}: {{p.name}}
  {{/each}}
{{/sortBy}}
